import{_ as t,o as r,c as e,a5 as o}from"./chunks/framework.CnBNXlt7.js";const g=JSON.parse('{"title":"注册会计师","description":"","frontmatter":{},"headers":[],"relativePath":"exam/certificate/cpa.md","filePath":"exam/certificate/cpa.md","lastUpdated":1733044928000}'),n={name:"exam/certificate/cpa.md"};function s(p,a,c,l,i,h){return r(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="注册会计师" tabindex="-1">注册会计师 <a class="header-anchor" href="#注册会计师" aria-label="Permalink to &quot;注册会计师&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">相关链接</p><ul><li>中国注册会计师协会：<a href="https://www.cicpa.org.cn/" target="_blank" rel="noreferrer">官网</a></li><li>网上报名：<a href="https://cpaexam.cicpa.org.cn/cpaexamhome" target="_blank" rel="noreferrer">入口</a></li></ul></div><h2 id="考试时间" tabindex="-1">考试时间 <a class="header-anchor" href="#考试时间" aria-label="Permalink to &quot;考试时间&quot;">​</a></h2><blockquote><p>参考2025年考试时间安排，<a href="https://cpaexam.cicpa.org.cn/files/articlehtml/statichtml/01/000001936CB0DA6357DB77D110DF633C.html" target="_blank" rel="noreferrer">细则</a></p></blockquote><div class="info custom-block"><p class="custom-block-title">2025年注册会计师全国统一考试报名时间和考试时间公告如下</p><p>发布于2024年11月27日</p><p>一、报名时间</p><p>2025年<strong>4月8日早8:00—4月30日晚8:00</strong>。</p><p>二、交费时间</p><p>2025年<strong>6月16日—6月30日（早8:00—晚8:00）</strong>。</p><p>三、考试时间</p><p>2025年<strong>8月23日—24日</strong>举行<strong>专业阶段</strong>考试（其中：会计科目将视报名情况，在部分考区实施两场考试）。</p><p>2025年<strong>8月24日</strong>举行<strong>综合阶段</strong>考试。</p><p>2025年8月30日—31日（比利时当地时间）举行欧洲考区考试。</p><p>具体安排请关注<a href="https://www.cicpa.org.cn/" target="_blank" rel="noreferrer">中国注册会计师协会网站</a>拟于2025年3月份发布的《2025年注册会计师全国统一考试报名简章》。</p></div><h2 id="考试科目与题型" tabindex="-1">考试科目与题型 <a class="header-anchor" href="#考试科目与题型" aria-label="Permalink to &quot;考试科目与题型&quot;">​</a></h2><h3 id="专业阶段考试" tabindex="-1">专业阶段考试 <a class="header-anchor" href="#专业阶段考试" aria-label="Permalink to &quot;专业阶段考试&quot;">​</a></h3><p><strong>专业阶段考试</strong>设会计、审计、财务成本管理、公司战略与风险管理、经济法、税法 6 个科目。<br> 各科考试均设置 5 分的英文作答附加分题，鼓励考生使用英文作答。 会计科目考试时间为 3 小时，审计、财务成本管理科目考试时间为 2.5 小时，公司战略与风险管理、经济法、税法科目考试时间为 2 小时。</p><p>专业阶段考试的题型主要分为三类：<br> （一）选择题，重点考察考生的知识理解能力。<br> （二）简答（分析）题、计算（分析）题，重点考察考生的基本应用能力。<br> （三）综合题、案例分析题，重点考察考生的综合运用能力。</p><h3 id="综合阶段考试" tabindex="-1">综合阶段考试 <a class="header-anchor" href="#综合阶段考试" aria-label="Permalink to &quot;综合阶段考试&quot;">​</a></h3><p><strong>综合阶段考试</strong>设职业能力综合测试科目，分成试卷一和试卷二（试卷一和试卷二各50分），考试题型为综合案例分析。<br> 试卷一以鉴证业务为重点，内容主要涉及会计、审计和税法等专业领域；试卷二以管理咨询和业务分析为重点，内容主要涉及财务成本管理、公司战略与风险管理和经济法等专业领域。试卷一设置5分的英文作答附加分题，鼓励考生使用英文作答。考试涉及的相关法规截至2023年12月31日。试卷一和试卷二考试时间均为3.5小时。</p><h2 id="试卷评阅和成绩认定" tabindex="-1">试卷评阅和成绩认定 <a class="header-anchor" href="#试卷评阅和成绩认定" aria-label="Permalink to &quot;试卷评阅和成绩认定&quot;">​</a></h2><p>（一）考生答卷由中注协组织集中评阅。考试成绩经财政部注册会计师考试委员会认定后发布。预计2025年11月下旬可登录网报系统查询成绩并下载打印成绩单，具体时间以中注协官网发布的通知公告为准。</p><p>（二）每科考试均实行百分制，<strong>60分</strong>为成绩合格分数线。</p><p>（三）专业阶段考试的单科考试合格成绩<strong>5年内</strong>有效。对在连续5个年度考试中取得专业阶段考试全部科目合格成绩的考生，颁发注册会计师全国统一考试专业阶段考试合格证电子证书，并由考生自行登录网报系统下载打印。</p><p>（四）对取得综合阶段考试科目合格成绩的考生，颁发注册会计师全国统一考试全科合格证书。全科合格证书由考生在成绩发布之日起45个工作日后，联系综合阶段考试报考所在地注协申领，具体领证事宜请以各省级注协通知为准。</p>',16)])])}const m=t(n,[["render",s]]);export{g as __pageData,m as default};
